## solution

#### depth first path

```cpp
#include <string>
#include <vector>
#include <unordered_set>

std::vector<std::string> treePath(Node* root, std::string targetVal) {
  if (root == nullptr) {
    return std::vector<std::string> {};
  }

  if (root->val == targetVal) {
    return std::vector<std::string> { root->val };
  }

  std::vector<std::string> leftPath = treePath(root->left, targetVal);
  if (leftPath.size() > 0) {
    leftPath.push_back(root->val);
    return leftPath;
  }

  std::vector<std::string> rightPath = treePath(root->right, targetVal);
  if (rightPath.size() > 0) {
    rightPath.push_back(root->val);
    return rightPath;
  }

  return std::vector<std::string> {};
}

std::string lowestCommonAncestor(Node* root, std::string val1, std::string val2) {
  std::vector<std::string> path1 = treePath(root, val1);
  std::vector<std::string> path2 = treePath(root, val2);
  std::unordered_set<std::string> set1 (path1.begin(), path1.end());
  for (std::string val : path2) {
    if (set1.count(val) > 0) {
      return val;
    }
  }
}
